constructor(address nextTreasury) {
    require(nextTreasury != address(0), "zero treasury");
    treasury = nextTreasury;
}

pragma solidity ^0.8.20;
contract OwnedRegistry {
    uint256 public constant MAX_CHAPTERS = 16;
    address public immutable owner;
    address public immutable treasury;
    constructor(address nextTreasury) { require(nextTreasury != address(0)); owner = msg.sender; treasury = nextTreasury; }
    function ownerAddress() external view returns (address) { return owner; }
}

